fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len();

    // Since k is guaranteed to be present,
    // the loop invariant is that k is in v[left..right]
    while left < right {
        let mid = left + (right - left) / 2;
        let mid_val = v[mid];

        if mid_val < k {
            left = mid + 1;
        } else if mid_val > k {
            right = mid;
        } else {
            // Found k at mid; return immediately
            return mid;
        }
    }

    // At this point, left == right and v[left] == k (by assumption)
    left
}